def set_param(content, param_name, param_value):
    """Set parameter value in nml content"""
    # Find the line with this parameter
    lines = content.split('\n')
    new_lines = []
    for line in lines:
        if param_name + ' =' in line:
            # Replace the value
            parts = line.split('=')
            if len(parts) >= 2:
                left = parts[0]
                new_lines.append(left + ' = ' + str(param_value))
            else:
                new_lines.append(line)
        else:
            new_lines.append(line)
    return '\n'.join(new_lines)

